mapper.select:
SELECT  FROM invoice_title
WHERE user_id=#{userId} AND region=#{region}
ORDER BY is_default DESC, id DESC

SELECT  FROM invoice_request
WHERE user_id=#{userId} AND region=#{region}
ORDER BY id DESC LIMIT #{limit} OFFSET #{offset}

SELECT  FROM invoice_request
WHERE region=#{region}
AND status=#{status}
ORDER BY id DESC LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE tax_rate
SET name=#{name},rate_bp=#{rateBp},status=#{status},updated_at=CURRENT_TIMESTAMP
WHERE id=#{id} AND region=#{region}
